147	// addr2line every pc in `pcs` against `elf_path`; unknown ("??") lines drop
148	// out, so absent keys mean "no source info".
149	std::map<uint64_t, std::string> resolve_sources(
150	    const std::string& addr2line_bin, const std::string& elf_path,
151	    const std::vector<uint64_t>& pcs) {
152	  std::map<uint64_t, std::string> result;
153	  if (addr2line_bin.empty() || pcs.empty()) return result;
154	  std::string input;
155	  for (uint64_t pc : pcs) {
156	    char buf[20];
157	    std::snprintf(buf, sizeof(buf), "0x%llx\n", (unsigned long long)pc);
158	    input += buf;
159	  }
160	  const std::string out =
161	      capture_with_stdin({addr2line_bin, "-e", elf_path}, input);
162	  std::istringstream ss(out);
163	  std::string line;
164	  size_t idx = 0;
165	  while (std::getline(ss, line) && idx < pcs.size()) {
166	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
167	      line.pop_back();
168	    if (!line.empty() && line.find("??") == std::string::npos)
169	      result[pcs[idx]] = line;
170	    ++idx;
171	  }
172	  return result;
173	}
