238	// mkdtemp workdir holding the staged qemu.cfg + the plugin log; removed on
239	// scope exit (the report is the product; there is nothing to keep).
240	struct Workdir {
241	  std::string path;
242	  std::string error;
243	  Workdir() {
244	    char tmpl[] = "/tmp/andesim-profile.XXXXXX";
245	    if (::mkdtemp(tmpl))
246	      path = tmpl;
247	    else
248	      error = "cannot create the profile workdir under /tmp";
249	  }
250	  ~Workdir() {
251	    if (path.empty()) return;
252	    std::error_code ec;
253	    fs::remove_all(path, ec);
254	  }
255	};
