44	
45	std::vector<LoopEdge> parse_plugin_log(const std::string& text) {
46	  std::vector<LoopEdge> rows;
47	  static const std::regex re(
48	      R"(\s*(0x[0-9a-fA-F]+)\s*,\s*(0x[0-9a-fA-F]+)\s*,\s*(\d+))");
49	  std::istringstream ss(text);
50	  std::string line;
51	  while (std::getline(ss, line)) {
52	    std::smatch m;
53	    if (!std::regex_search(line, m, re)) continue;
54	    rows.push_back({std::stoull(m[1], nullptr, 16),
55	                    std::stoull(m[2], nullptr, 16), std::stoull(m[3])});
56	  }
57	  return rows;
58	}
