25	// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
26	std::string state_path(const std::string& workdir, size_t i) {
27	  return workdir + "/state-" + std::to_string(i) + ".bin";
28	}
29	
30	// L2: keep at most this many failure bundles; older ones are pruned.
31	constexpr size_t kMaxReproBundles = 20;
32	
33	// Drop the oldest bundles (dir names start with a UTC timestamp, so the
34	// lexicographic order IS the age order) until at most `keep` remain.
35	void prune_repro_bundles(const fs::path& root, size_t keep) {
36	  std::error_code ec;
37	  std::vector<fs::path> dirs;
38	  for (const auto& e : fs::directory_iterator(root, ec))
39	    if (e.is_directory(ec)) dirs.push_back(e.path());
40	  if (dirs.size() <= keep) return;
41	  std::sort(dirs.begin(), dirs.end());  // oldest first
42	  for (size_t i = 0; i + keep < dirs.size(); ++i) fs::remove_all(dirs[i], ec);
43	}
44	
45	// L2: on a leg failure, keep the run's evidence so the bug can be reported
46	// and reproduced: the workdir files (drained states, LM sidecars, staged
47	// qemu cfg), a copy of the ELF, and manifest.txt with the error and every
48	// leg's exact command. The big shared mmap is NOT kept (the legs are
49	// deterministic; re-running the kept commands regenerates it). Returns the
50	// bundle dir, or "" when it cannot be written (never fails the caller).
51	std::string save_repro_bundle(const std::string& wd, const Plan& plan,
52	                              const std::vector<std::vector<std::string>>& argvs,
53	                              size_t failed_step, const std::string& error) {
54	  const std::string cache = andesim_cache_dir();
55	  if (cache.empty()) return "";
56	  std::error_code ec;
57	  const fs::path root = fs::path(cache) / "repro";
58	  fs::create_directories(root, ec);
59	  if (ec) return "";
60	
61	  char ts[32];
62	  const std::time_t now = std::time(nullptr);
63	  std::tm tm{};
64	  gmtime_r(&now, &tm);
65	  std::strftime(ts, sizeof(ts), "%Y%m%dT%H%M%SZ", &tm);
66	  const std::string stem = fs::path(plan.elf).stem().string();
67	  fs::path dir = root / (std::string(ts) + "-" + stem);
68	  for (int n = 1; fs::exists(dir, ec); ++n)  // same-second collisions
69	    dir = root / (std::string(ts) + "-" + stem + "." + std::to_string(n));
70	  fs::create_directories(dir, ec);
71	  if (ec) return "";
72	
73	  fs::copy(wd, dir, fs::copy_options::recursive, ec);  // whatever the legs left
74	  fs::copy_file(plan.elf, dir / fs::path(plan.elf).filename(),
75	                fs::copy_options::skip_existing, ec);
76	
77	  std::ofstream m(dir / "manifest.txt");
78	  m << "error: " << error << "\n";
79	  m << "elf: " << plan.elf << "\n";
80	  m << "failed step: " << failed_step << " (" << plan.steps[failed_step].role
81	    << " [" << plan.steps[failed_step].engine_id << "])\n";
82	  for (size_t i = 0; i < argvs.size(); ++i)
83	    m << "step " << i << " " << plan.steps[i].role << " ["
84	      << plan.steps[i].engine_id << "]: " << render_argv(argvs[i]) << "\n";
85	  m << "note: the shared mmap is not kept; the commands above regenerate the "
86	       "run deterministically\n";
87	  m.close();
88	
89	  prune_repro_bundles(root, kMaxReproBundles);
90	  return dir.string();
91	}
92	
93	const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
94	                                    const std::string& id) {
95	  for (const EngineDescriptor& e : engines)
96	    if (e.id == id) return &e;
97	  return nullptr;
98	}
99	
100	// $VSIM_PLUGIN else the in-repo default (matches the e2e harness).
101	std::string resolve_plugin(const std::string& override_path) {
102	  if (!override_path.empty()) return override_path;
103	  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
104	  return default_plugin_path().string();
105	}
106	
107	// `--print-qemu-config` exits in the arg parser (no simulation), so the probe is
108	// cheap; this is a safety cap, not a real wait.
109	constexpr int kQemuCfgProbeMs = 5000;
110	
111	}  // namespace
112	
113	// The engine whose hardware this plan's fast leg(s) must model: the plan's
114	// explicit hw_engine_id (the --verify oracle plan, which has no accurate leg
115	// of its own), else its first accurate-leg step's engine.
116	static const EngineDescriptor* plan_hw_engine(
117	    const Plan& plan, const std::vector<EngineDescriptor>& engines) {
118	  if (!plan.hw_engine_id.empty())
119	    return find_engine(engines, plan.hw_engine_id);
120	  for (const Step& s : plan.steps)
121	    if (s.role == "accurate-leg")
122	      return find_engine(engines, s.engine_id);
123	  return nullptr;
