144	std::string stage_qemu_cfg(const std::string& workdir, const RunResult& probe) {
145	  if (probe.spawn_failed || probe.timed_out || probe.rc != 0 || probe.out.empty())
146	    return "";
147	  const std::string path = workdir + "/qemu.cfg";
148	  std::ofstream f(path, std::ios::binary | std::ios::trunc);
149	  f.write(probe.out.data(), static_cast<std::streamsize>(probe.out.size()));
150	  if (!f) return "";
151	  return path;
152	}
153	
154	std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
155	                               int got_rc) {
156	  std::string m = "plan step " + std::to_string(step) + ": expected exit " +
157	                  std::to_string(expect_rc) + ", got " + std::to_string(got_rc);
158	  // A drain step (expect_rc is the handoff/drain code) that exits 0 ran the ELF
159	  // to completion without ever hitting its ROI boundary -- the marker/pc
160	  // trigger never fired. This is THE common "unmarked ELF / wrong trigger"
161	  // mistake; name the kind so the fix is obvious, not a bare exit code.
162	  if (got_rc == 0 && expect_rc == kDrainRc)
163	    m += " -- the " + s.role + " ran to completion without reaching its " +
164	         s.trigger.kind +
165	         " trigger boundary (the ROI never drained; check the ELF actually "
166	         "reaches the " +
167	         s.trigger.kind + ")";
168	  return m;
169	}
170	
171	LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
172	                                std::string& err) {
173	  err.clear();
174	  LegTriggerArgs out;
175	  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv
176	
177	  const bool fast = role == "fast-leg";
178	  const bool accurate = role == "accurate-leg";
179	  if (!fast && !accurate) return out;  // other roles carry no trigger args
180	
181	  // Required-param lookup. A missing key is a caller bug; surface it (don't
182	  // throw) so plan_argvs can report which step failed.
183	  auto param = [&](const char* key) -> const std::string* {
184	    auto it = t.params.find(key);
185	    if (it == t.params.end()) {
186	      err = "trigger '" + t.kind + "' missing param '" + key + "'";
187	      return nullptr;
188	    }
189	    return &it->second;
190	  };
191	
192	  if (t.kind == "pc") {
193	    if (fast) {
194	      if (const std::string* p = param("enter_pc"))
195	        out.plugin_suffix = ",enter_pc=" + *p;
196	    } else if (const std::string* p = param("exit_pc")) {
197	      out.extra = {"--hybrid-exit-pc", *p};
198	    }
199	    return out;
200	  }
201	
202	  // verify oracle leg (verify_oracle F4): a pure-QEMU drain at the ROI exit
203	  // boundary, sampling at vsim's actual halt pc (drain_pc -- the DMI halt
204	  // lands a few insns past the trigger, and the comparison is only valid at
205	  // the same architectural point). qemu-only: the oracle plan has no
206	  // accurate leg.
207	  if (t.kind == "verify-marker" || t.kind == "verify-pc") {
208	    if (!fast) return out;
209	    std::string suffix = ",exit_marker=1";
210	    if (t.kind == "verify-pc") {
211	      const std::string* p = param("exit_pc");
212	      if (!p) return out;
213	      suffix = ",exit_pc=" + *p;
214	    }
215	    if (const std::string* p = param("drain_pc"))
216	      out.plugin_suffix = suffix + ",drain_pc=" + *p;
217	    return out;
218	  }
219	
220	  err = "unknown trigger kind '" + t.kind + "'";
221	  return out;
222	}
223	
224	std::vector<std::vector<std::string>> plan_argvs(
225	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
226	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
227	  std::vector<std::vector<std::string>> out;
228	  out.reserve(plan.steps.size());
229	  std::string prev_state_out;  // empty for the cold first leg
230	
231	  // hw-config sync: {vlen} comes from the hw-reference engine's descriptor
232	  // (the accurate-leg engine, or plan.hw_engine_id for the oracle plan).
233	  long vlen = 0;
234	  // LM content transport (ROADMAP_ilm_dlm F3) + HVM (ROADMAP_hvm F3): the
235	  // accurate engine's memory sizes (bytes, from its descriptor) arm the QEMU
236	  // plugin's sidecar drain and the vsim leg's --ilm/--dlm/--hvm backdoor
237	  // load. 0 = that engine has no such memory -> neither leg grows an arg.
238	  long ilm_size = 0, dlm_size = 0, hvm_size = 0;
239	  if (const EngineDescriptor* e = plan_hw_engine(plan, engines)) {
240	    if (e->vlen > 0) vlen = e->vlen;
241	    if (e->ilm_size > 0) ilm_size = e->ilm_size;
242	    if (e->dlm_size > 0) dlm_size = e->dlm_size;
243	    if (e->hvm_size > 0) hvm_size = e->hvm_size;
244	  }
245	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
246	  std::string lm_suffix;
247	  if (ilm_size > 0) lm_suffix += ",ilm_size=" + std::to_string(ilm_size);
248	  if (dlm_size > 0) lm_suffix += ",dlm_size=" + std::to_string(dlm_size);
249	  if (hvm_size > 0) lm_suffix += ",hvm_size=" + std::to_string(hvm_size);
250	
251	  for (size_t i = 0; i < plan.steps.size(); ++i) {
252	    const Step& step = plan.steps[i];
253	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
254	    if (!eng) {
255	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
256	            step.engine_id + "'";
257	      return {};
258	    }
259	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
260	    if (!tmpl) {
261	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
262	            "' has no invoke template for role '" + step.role + "'";
263	      return {};
264	    }
265	
266	    std::string trig_err;
267	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
268	    if (!trig_err.empty()) {
269	      err = "plan step " + std::to_string(i) + ": " + trig_err;
270	      return {};
271	    }
272	
273	    const std::string state_out = state_path(workdir, i);
274	    // {plugin_args} is the qemu plugin comma-suffix: trigger args (empty for
275	    // marker) plus the LM sidecar-drain args (empty for a no-LM engine) plus
276	    // the forwarded log level (L4: one --log-level drives the whole pipeline).
277	    // {trigger} is its compatibility alias -- the name templates used before
278	    // non-trigger args joined the suffix (build_argv ignores unused keys).
279	    const std::string plugin_args = lt.plugin_suffix + lm_suffix +
280	                                    ",log_level=" +
281	                                    std::to_string(log_threshold());
282	    const std::map<std::string, std::string> m = {
283	        {"bin", eng->bin_path},
284	        {"elf", plan.elf},
285	        {"plugin", ctx.plugin_path},
286	        {"mmap", ctx.mmap_path},
287	        {"mmap_size", std::to_string(ctx.mem_size)},
288	        {"mmap_base", ctx.mmap_base},
289	        {"state_in", prev_state_out},
290	        {"state_out", state_out},
291	        {"plugin_args", plugin_args},
292	        {"trigger", plugin_args},
293	        {"vlen", vlen_str},
294	        // {qemu_cpu}: the model the readconfig globals target; the family
295	        // default when the engine has no --print-qemu-config hook.
296	        {"qemu_cpu", ctx.qemu_cpu.empty() ? "andes-ax45mpv" : ctx.qemu_cpu},
297	    };
298	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
299	    if (!err.empty()) {
300	      err = "plan step " + std::to_string(i) + ": " + err;
301	      return {};
302	    }
303	    // The QEMU producer leg loads the accurate engine's ISA via -readconfig (its
304	    // config.inc distilled to per-extension globals), so QEMU1 executes the same
305	    // extensions the engine models. Empty => keep the descriptor's default -cpu.
306	    if (step.role == "fast-leg" && !ctx.qemu_cfg.empty()) {
307	      argv.push_back("-readconfig");
308	      argv.push_back(ctx.qemu_cfg);
309	    }
310	    // LM content transport (F3): point the vsim leg at the sidecars its
311	    // producer drained next to state_in (--ilm/--dlm backdoor load).
312	    if (step.role == "accurate-leg") {
313	      if (ilm_size > 0) {
314	        argv.push_back("--ilm");
315	        argv.push_back(prev_state_out + ".ilm");
316	      }
317	      if (dlm_size > 0) {
318	        argv.push_back("--dlm");
319	        argv.push_back(prev_state_out + ".dlm");
320	      }
321	      if (hvm_size > 0) {
322	        argv.push_back("--hvm");
323	        argv.push_back(prev_state_out + ".hvm");
324	      }
325	    }
326	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
327	    // after the filled template (matches tests/e2e.sh's ordering).
328	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
329	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
330	    out.push_back(std::move(argv));
331	    prev_state_out = state_out;
332	  }
333	  err.clear();
334	  return out;
335	}
336	
337	PlanResult run_plan(const Plan& plan,
338	                    const std::vector<EngineDescriptor>& engines,
339	                    const PlanOptions& opts) {
340	  PlanResult res;
341	  if (plan.steps.empty()) {
342	    res.error = "plan has no steps";
343	    return res;
344	  }
345	
346	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
347	  std::string mmap_path = plan.mmap_path;
348	  const bool own_mmap = mmap_path.empty();
349	  if (own_mmap) {
350	    std::string err;
351	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
352	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
353	    if (mmap_path.empty()) {
354	      res.error = err;
355	      return res;
356	    }
357	  }
358	
359	  // A private dir for the threaded drain files.
360	  std::error_code ec;
361	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
362	  std::string tmpl = workdir.string();
363	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
364	  tbuf.push_back('\0');
365	  const char* made = ::mkdtemp(tbuf.data());
366	  if (!made) {
367	    if (own_mmap) ::unlink(mmap_path.c_str());
368	    res.error = "failed to create plan work dir";
369	    return res;
370	  }
371	  const std::string wd = made;
372	
373	  RuntimeCtx ctx;
374	  ctx.mmap_path = mmap_path;
375	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
376	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
377	  // linker script still uses only --mem-size, so the scratch page sits above
378	  // everything it can address.
379	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
380	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
381	
382	  // Match the QEMU producer leg's ISA to the hw-reference engine (the
383	  // accurate-leg engine, or plan.hw_engine_id for the --verify oracle plan):
384	  // ask that engine for a QEMU -readconfig cfg distilled from its config.inc.
385	  // Tolerant -- an engine without --print-qemu-config leaves qemu_cfg empty
386	  // (the parser throws on the unknown flag -> non-zero exit), so the fast leg
387	  // keeps its -cpu.
388	  if (const EngineDescriptor* e = plan_hw_engine(plan, engines);
389	      e && !e->bin_path.empty()) {
390	    const RunResult probe =
391	        run_process({e->bin_path, "--print-qemu-config"}, kQemuCfgProbeMs);
392	    ctx.qemu_cfg = stage_qemu_cfg(wd, probe);
393	    // The cfg's globals only apply to the CPU driver they name, so the
394	    // fast leg instantiates that same model ({qemu_cpu} fill).
395	    if (!ctx.qemu_cfg.empty()) ctx.qemu_cpu = qemu_cpu_from_cfg(probe.out);
396	  }
397	
398	  std::string err;
399	  const std::vector<std::vector<std::string>> argvs =
400	      plan_argvs(plan, engines, wd, ctx, err);
401	  if (!err.empty()) {
402	    res.error = err;
403	  } else if (opts.dry_run) {
404	    // Build-only: the argvs are fully resolved (placeholders, staged qemu_cfg,
405	    // threaded state paths) -- record them for the caller to print, spawn none.
406	    res.argvs = argvs;
407	  } else {
408	    res.argvs = argvs;
409	    // A failing leg keeps the evidence (L2) next to its error.
410	    const auto fail_step = [&](size_t i, const std::string& msg) {
411	      res.error = msg;
412	      res.repro_dir = save_repro_bundle(wd, plan, argvs, i, msg);
413	    };
414	    for (size_t i = 0; i < argvs.size(); ++i) {
415	      // trace: the fully resolved command, copy-pasteable to re-run this leg.
416	      log_line(kLogTrace, "[andesim] exec %s [%s]: %s",
417	               plan.steps[i].role.c_str(), plan.steps[i].engine_id.c_str(),
418	               render_argv(argvs[i]).c_str());
419	      // At debug the legs' stderr streams through live (vsim's own leveled
420	      // log, the plugin's drain summary); at info and above it stays dropped.
421	      const RunResult r =
422	          run_process(argvs[i], opts.timeout_ms, log_on(kLogDebug));
423	      if (r.spawn_failed) {
424	        fail_step(i, "plan step " + std::to_string(i) + ": failed to spawn");
425	        break;
426	      }
427	      if (r.timed_out) {
428	        fail_step(i, "plan step " + std::to_string(i) + ": timed out after " +
429	                         std::to_string(opts.timeout_ms) + " ms");
430	        break;
431	      }
432	      if (r.rc != opts.expect_rc) {
433	        fail_step(i, plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc));
434	        break;
435	      }
436	      const StateFile sf = read_state_file(state_path(wd, i));
437	      if (!sf.ok()) {
438	        fail_step(i, "plan step " + std::to_string(i) + ": " + sf.error);
439	        break;
440	      }
441	      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out, sf.st});
442	    }
443	  }
444	
445	  fs::remove_all(wd, ec);
446	  if (own_mmap) ::unlink(mmap_path.c_str());
447	  return res;
448	}
449	
450	}  // namespace andes_sim
