1	// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <algorithm>
12	#include <chrono>
13	#include <cstdint>
14	#include <cstdio>
15	#include <cstdlib>
16	#include <filesystem>
17	#include <optional>
18	#include <string>
19	#include <string_view>
20	#include <thread>
21	#include <vector>
22	
23	#include "argv.hpp"
24	#include "cli.hpp"
25	#include "elf_syms.hpp"
26	#include "engine_descriptor.hpp"
27	#include "engine_registry.hpp"
28	#include "hybrid.hpp"
29	#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES (L26/F3 overlap check)
30	#include "log.hpp"
31	#include "memmap.hpp"
32	#include "models.hpp"
33	#include "plan.hpp"
34	#include "process.hpp"
35	#include "repo_root.hpp"
36	#include "run_passthrough.hpp"
37	#include "run_plan.hpp"
38	#include "shm.hpp"
39	#include "state.hpp"
40	#include "state_diff.hpp"
41	#include "vsim_filter.hpp"
42	
43	namespace fs = std::filesystem;
44	
45	namespace andes_sim {
46	namespace {
47	
48	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
49	// success; on failure prints an error tagged with `ctx` and returns "". The
50	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
51	// missing path fails with a clear "ELF not found" instead of being handed to the
52	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
53	// up-front check run_hybrid already does.
54	std::string abs_elf(const std::string& path, const std::string& ctx) {
55	  std::error_code ec;
56	  fs::path abs = fs::absolute(path, ec);
57	  if (ec) {
58	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
59	                 ctx.c_str(), path.c_str());
60	    return "";
61	  }
62	  if (!fs::is_regular_file(abs, ec)) {
63	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
64	                 path.c_str());
65	    return "";
66	  }
67	  return abs.string();
68	}
69	
70	// Validate the lone-ELF positional shape the standalone models require: print
71	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
72	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
73	// spawns a --describe subprocess per Verilator build). `model` labels the error.
74	int check_one_elf(const Cli& cli, const char* model) {
75	  if (cli.positional.empty()) {
76	    std::fprintf(stderr,
77	                 "andesim run --mode %s: missing ELF (the workload to run; "
78	                 "e.g. a tests/fixtures/<name>.elf)\n",
79	                 model);
80	    return 2;
81	  }
82	  if (cli.positional.size() > 1) {
83	    std::fprintf(stderr,
84	                 "andesim run --mode %s: unexpected argument '%s' "
85	                 "(engine args go after --)\n",
86	                 model, cli.positional[1].c_str());
87	    return 2;
88	  }
89	  return 0;
90	}
91	
92	// elf_engine_arch_error (the ELF-vs-engine width guard shared with profile)
93	// lives in engine_registry.hpp, next to resolve_accurate_engine.
94	
95	// print_dry_run (the shared --dry-run preview) lives in argv.hpp, next to
96	// render_argv.
97	
98	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
99	// and verbose [info] log (VsimFilter), relaying only the program's own output
100	// and any real diagnostics, then restate the lifted cycle count as andesim's own
101	// one-line result under the [andesim] prefix. The count is printed AFTER the run
102	// (the engine logs it at exit), so it follows the program output. Returns the
103	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
104	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
105	int run_cycle_clean(const std::vector<std::string>& argv) {
106	  VsimFilter filter;
107	  const int rc = run_line_filtered(
108	      argv, [&filter](int stream, std::string_view line) {
109	        std::FILE* dst = nullptr;
110	        switch (filter.classify(stream, line)) {
111	          case VsimFilter::Dest::kStdout: dst = stdout; break;
112	          case VsimFilter::Dest::kStderr: dst = stderr; break;
113	          case VsimFilter::Dest::kDrop: return;
114	        }
115	        std::fwrite(line.data(), 1, line.size(), dst);
116	        std::fputc('\n', dst);
117	      });
118	  if (const std::optional<uint64_t> c = filter.cycles())
119	    log_result(kLogInfo, "[andesim] %llu cycles",
120	               static_cast<unsigned long long>(*c));
121	  return rc;
122	}
123	
124	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
125	// then run the resolved engine standalone with `extra` (model flags the
126	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
127	// `clean_output` picks how the engine's output is presented: fast inherits the
128	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
129	// semihosting console works unchanged); cycle filters out the engine's banner +
130	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
131	// exit code propagates. The per-model engine + selection are resolved by the
132	// caller; `model` here only labels the positional diagnostics.
133	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
134	                   const char* model, const std::vector<std::string>& extra = {},
135	                   bool clean_output = false) {
136	  if (int rc = check_one_elf(cli, model)) return rc;
137	  // QEMU's -bios flag searches its data directory for relative paths rather
138	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
139	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
140	  if (elf.empty()) return 2;
141	  std::vector<std::string> args = extra;
142	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
143	  std::string err;
144	  const std::vector<std::string> argv =
145	      passthrough_argv(eng, "standalone", elf, args, err);
146	  if (!err.empty()) {
147	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
148	    return 2;
149	  }
150	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
151	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
152	  if (cli.dry_run)
153	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
154	  // Trace mirrors the hybrid legs' exec lines: emitted BEFORE the spawn, so a
155	  // wedged engine still leaves the exact command in the log.
156	  log_line(kLogTrace, "[andesim] exec standalone [%s]: %s", eng.id.c_str(),
157	           render_argv(argv).c_str());
158	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
159	}
160	
161	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
162	// only the built-in qemu descriptor, so it resolves that directly rather than
163	// discover_engines(), which would spawn a --describe subprocess per Verilator
164	// build only to discard them all here.
165	int run_fast(const Cli& cli) {
166	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
167	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
168	    std::fprintf(stderr,
169	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
170	                 "got '%s'\n",
171	                 cli.engine.c_str());
172	    return 2;
173	  }
174	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
175	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
176	  std::string err;
177	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
178	  if (!err.empty()) {
179	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
180	    return 2;
181	  }
182	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
183	  if (cli.gdb) {
184	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
185	    extra.push_back("-gdb");
186	    extra.push_back("tcp::" + port);
187	    extra.push_back("-S");
188	  }
189	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
190	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
191	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
192	  // ELF -- the override is the user's call.
193	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
194	  int xlen;
195	  if (cli.engine == kQemuId32) xlen = 32;
196	  else if (cli.engine == kQemuId64) xlen = 64;
197	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
198	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
199	  // == elf_w), so this guard already implies an explicit --engine.
200	  if (elf_w && elf_w != xlen)
201	    std::fprintf(stderr,
202	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
203	                 "(running as rv%d)\n",
204	                 cli.engine.c_str(), xlen, elf_w, xlen);
205	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
206	}
207	
208	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
209	// its --jtag-port only after it has reset and halted the hart, so the debugger we
210	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
211	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
212	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
213	// single debugger slot). Returns false on timeout.
214	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
215	  constexpr int kPollMs = 50;
216	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
217	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
218	      char line[512];
219	      while (std::fgets(line, sizeof line, f)) {
220	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
221	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
222	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
223	        unsigned lport = 0, st = 0;
224	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
225	            && st == 0x0A && lport == port) {
226	          std::fclose(f);
227	          return true;
228	        }
229	      }
230	      std::fclose(f);
231	    }
232	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
233	  }
234	  return false;
235	}
236	
237	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
238	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
239	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
240	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
241	  const char* iceman = std::getenv("ICEMAN");
242	  if (!iceman || !*iceman) {
243	    std::fprintf(stderr,
244	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
245	                 "(export ICEMAN=<path to ICEman binary>)\n");
246	    return 2;
247	  }
248	  // Build vsim argv from the standalone template, appending user passthrough
249	  // and the JTAG port flag.
250	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
251	  if (elf.empty()) return 2;
252	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
253	  std::vector<std::string> vsim_pass = cli.passthrough;
254	  vsim_pass.push_back("--jtag-port");
255	  vsim_pass.push_back(jtag_port);
256	  std::string err;
257	  const std::vector<std::string> vsim_argv =
258	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
259	  if (!err.empty()) {
260	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
261	    return 2;
262	  }
263	  std::fprintf(stderr,
264	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
265	               jtag_port.c_str());
266	  if (fork_background(vsim_argv) < 0) {
267	    std::fprintf(stderr,
268	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
269	    return 1;
270	  }
271	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
272	  // Wait for the port to be LISTENing before launching the debugger (it does not
273	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
274	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
275	  // but launch anyway if it never appears.
276	  if (const int pnum = std::atoi(jtag_port.c_str());
277	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
278	    std::fprintf(stderr,
279	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
280	                 "after 20s; launching the debugger anyway\n",
281	                 jtag_port.c_str());
282	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
283	  // localhost, port 9104) instead of its default real-hardware adapter; without
284	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
285	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
286	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
287	}
288	
289	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
290	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
291	// engine's own output. Unlike fast, this must discover the Verilator build(s)
292	// to resolve the engine (explicit --engine, else the sole one).
293	int run_accurate(const Cli& cli) {
294	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
295	  // --describe subprocess per Verilator build only to fail on the argument.
296	  if (int rc = check_one_elf(cli, "cycle")) return rc;
297	  // --mem-size is validated but has nothing to size: the cycle engine always
298	  // models its full DRAM window. Say so instead of silently ignoring it.
299	  if (!cli.mem_size.empty()) {
300	    std::string se;
301	    if (parse_size(cli.mem_size, se); !se.empty()) {
302	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
303	                   se.c_str());
304	      return 2;
305	    }
306	    log_line(kLogWarn,
307	             "[andesim] --mem-size: the cycle engine models its full "
308	             "DRAM window; nothing to size");
309	  }
310	  Discovery disc = discover_engines();
311	  std::string err;
312	  const EngineDescriptor* eng =
313	      resolve_accurate_engine(disc.engines, cli.engine, err);
314	  if (!eng) {
315	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
316	    // Surface why an expected engine may be absent (failed --describe, etc.).
317	    for (const std::string& w : disc.warnings)
318	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
319	    return 2;
320	  }
321	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
322	  // vice versa) cannot run. Catch it here with a clear message instead of the
323	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
324	  // positional.
325	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
326	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
327	    return 2;
328	  }
329	  // --dry-run previews the standalone command and spawns nothing, so it takes
330	  // precedence over the interactive --gdb path (a dry run launches no debugger).
331	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
332	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
333	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
334	  // monitor/gdbstub are interactive).
335	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
336	}
337	
338	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
339	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
340	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
341	// driver's tests/e2e.sh delegation with a single window-cycle line.
342	int run_hybrid(const Cli& cli) {
343	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
344	  auto fail = [](const std::string& msg) {
345	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
346	    return 2;
347	  };
348	
349	  // --print-memmap: the map describes the run's window (engine + --mem-size),
350	  // not a workload, so the ELF is optional (when given it only adds the
351	  // fit-vs-scratch note) and the trigger machinery is skipped entirely.
352	  const bool memmap_only = cli.print_memmap;
353	  if (!memmap_only) {
354	    if (int rc = check_one_elf(cli, "hybrid")) return rc;
355	  } else if (cli.positional.size() > 1) {
356	    return fail("unexpected argument '" + cli.positional[1] + "'");
357	  }
358	
359	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
360	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
361	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
362	  std::string elf_path;
363	  if (!cli.positional.empty()) {
364	    elf_path = abs_elf(cli.positional[0], "--mode hybrid");
365	    if (elf_path.empty()) return 2;
366	  }
367	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
368	
369	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
370	  // mistake fails fast without spawning a --describe per Verilator build.
371	  std::string err;
372	  Trigger trig;
373	  std::vector<std::string> vsim_extras;
374	  if (!memmap_only) {
375	    trig = hybrid_trigger(cli, elf_path, err);
376	    if (!err.empty()) return fail(err);
377	
378	    // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
379	    // hybrid triggers; unknown returned an error above) -- exactly the entry
380	    // boundary --verify needs the oracle to arm on.
381	    vsim_extras = vsim_extra_args(cli, trig.kind, err);
382	    if (!err.empty()) return fail(err);
383	  }
384	
385	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
386	  if (!cli.mem_size.empty()) {
387	    std::string se;
388	    mem = parse_size(cli.mem_size, se);
389	    if (!se.empty()) return fail("--mem-size: " + se);
390	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
391	    // guest RAM here. The physical mmap reserves one V-scratch page above the
392	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
393	    // page. Failing now beats allocating a huge mmap file first and letting
394	    // QEMU die late.
395	    if (mem > max_program_mem_bytes())
396	      return fail("--mem-size " + cli.mem_size +
397	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
398	                  "reservation)");
399	  }
400	
401	  // L26/F3: refuse a run whose static image would extend into the reserved
402	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
403	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
404	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
405	  // scratch -> silent corruption. Derive the page's start from
406	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
407	  // `mem`, so the threshold tracks the reservation shape instead of relying on
408	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
409	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
410	  // reports it.
411	  {
412	    std::string e;
413	    const uint64_t top = elf_load_top(elf_path, e);
414	    const uint64_t scratch_gpa =
415	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
416	    if (e.empty() && top > scratch_gpa) {
417	      char msg[256];
418	      std::snprintf(msg, sizeof(msg),
419	                    "ELF static image ends at 0x%llx, overlapping the reserved "
420	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
421	                    "; raise --mem-size or shrink the image",
422	                    static_cast<unsigned long long>(top),
423	                    static_cast<unsigned long long>(scratch_gpa));
424	      return fail(msg);
425	    }
426	  }
427	
428	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
429	  // or the sole cycle-accurate engine (reusing the F8 selector).
430	  Discovery disc = discover_engines();
431	  const EngineDescriptor* acc =
432	      resolve_accurate_engine(disc.engines, cli.engine, err);
433	  if (!acc) {
434	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
435	    for (const std::string& w : disc.warnings)
436	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
437	    return 2;
438	  }
439	
440	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
441	  // cannot share architectural state with the rv64 fast leg).
442	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
443	  // ...and the ELF must match that engine width too (same guard as cycle).
444	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
445	    return fail(e);
446	
447	  if (memmap_only) {
448	    // The LM/HVM bases come from the same probe run_plan stages as the fast
449	    // leg's -readconfig, so the printed geometry IS the run's effective one.
450	    // Tolerant like stage_qemu_cfg: a probe failure only drops the LM rows
451	    // (hybrid_memmap warns).
452	    const RunResult probe =
453	        run_process({acc->bin_path, "--print-qemu-config"}, 5000);
454	    const std::string cfg =
455	        (!probe.spawn_failed && !probe.timed_out && probe.rc == 0) ? probe.out
456	                                                                   : "";
457	    std::fprintf(stderr, "[andesim] hybrid memory map: engine=%s mem-size=%s\n",
458	                 acc->id.c_str(),
459	                 fmt_size(static_cast<uint64_t>(mem)).c_str());
460	    std::fputs(render_memmap(hybrid_memmap(*acc, mem, cfg)).c_str(), stdout);
461	    // With an ELF given, say where its static image lands in that window.
462	    if (!elf_path.empty()) {
463	      std::string e;
464	      const uint64_t top = elf_load_top(elf_path, e);
465	      if (e.empty())
466	        std::printf("ELF %s: static image top 0x%llx (%s)\n",
467	                    elf.stem().string().c_str(),
468	                    static_cast<unsigned long long>(top),
469	                    top <= static_cast<uint64_t>(mem)
470	                        ? "fits DRAM"
471	                        : "OVERLAPS the reserved V-scratch page; raise "
472	                          "--mem-size");
473	    }
474	    return 0;
475	  }
476	
477	  Plan plan;
478	  plan.elf = elf_path;
479	  plan.mem_size = mem;
480	  Step qemu_step{kQemuId64, "fast-leg", trig};
481	  Step vsim_step{acc->id, "accurate-leg", trig};
482	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
483	  // #1: with no --verify the driver consumes only the vsim mcycle delta, so ask
484	  // the accurate leg to drain just the counters and skip the full register-file
485	  // readback (~190 DM abstract commands). --verify keeps the full drain so the
486	  // oracle diff sees every field. Driver policy lives here next to the rest of
487	  // the verify reasoning, not in vsim_extra_args (user-forwarded flags only).
488	  if (!cli.verify)
489	    vsim_step.extra_args.push_back("--drain-minimal");
490	  // L4: the vsim leg speaks the same --log-level scale; forward ours so one
491	  // flag tunes the whole pipeline (its stderr is relayed at <= debug).
492	  vsim_step.extra_args.push_back("--log-level");
493	  vsim_step.extra_args.push_back(std::to_string(log_threshold()));
494	  plan.steps = {qemu_step, vsim_step};
495	
496	  // Banner to stderr so the window-cycle result stands alone on stdout.
497	  // vlen is the synced value the fast leg inherits from the engine.
498	  log_line(kLogDebug,
499	           "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s",
500	           acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
501	           elf.stem().string().c_str());
502	  // L3 decision log: why THIS engine.
503	  log_line(kLogDebug, "[andesim] engine: %s (%s)", acc->id.c_str(),
504	           cli.engine.empty() ? "sole cycle-accurate engine"
505	                              : "selected by --engine");
506	
507	  PlanOptions opts;
508	  opts.dry_run = cli.dry_run;
509	  const PlanResult r = run_plan(plan, disc.engines, opts);
510	  if (!r.ok()) {
511	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
512	    if (!r.repro_dir.empty())
513	      std::fprintf(stderr,
514	                   "[andesim] repro: kept run artifacts at %s "
515	                   "(see manifest.txt)\n",
516	                   r.repro_dir.c_str());
517	    if (!log_file_path().empty())
518	      std::fprintf(stderr, "[andesim] repro: full log at %s\n",
519	                   log_file_path().c_str());
520	    return 1;
521	  }
522	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
523	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
524	  // then the vsim accurate leg -- and stop. Nothing was spawned.
525	  if (cli.dry_run) {
526	    std::vector<std::string> labels;
527	    labels.reserve(plan.steps.size());
528	    for (const Step& s : plan.steps)
529	      labels.push_back(s.role + " [" + s.engine_id + "]");
530	    return print_dry_run(r.argvs, labels);
531	  }
532	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
533	  // then anything the ROI wrote on vsim) belong to the user. The vsim
534	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
535	  // Version) -- strip it so only real program output shows, the same as `cycle`
536	  // does; its [info] log is already absent (the leg's stderr was dropped at
537	  // capture). The QEMU leg has no banner, so it relays verbatim.
538	  for (size_t i = 0; i < r.phases.size(); ++i) {
539	    const std::string& out = r.phases[i].out;
540	    if (out.empty()) continue;
541	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
542	      const std::string shown = strip_vsim_banner(out);
543	      std::fwrite(shown.data(), 1, shown.size(), stdout);
544	    } else {
545	      std::fwrite(out.data(), 1, out.size(), stdout);
546	    }
547	  }
548	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
549	  // vsim mcycle delta.
550	  {
551	    const unsigned long long q_mc = r.phases[0].mcycle;
552	    const unsigned long long v_mc = r.phases[1].mcycle;
553	    // The answer line, same shape as cycle mode; the raw mcycle operands are
554	    // debug detail.
555	    log_result(kLogInfo, "[andesim] %llu cycles", v_mc - q_mc);
556	    log_result(kLogDebug,
557	               "[andesim] window: trigger=%s vsim mcycle=%llu qemu mcycle=%llu",
558	               trig.kind.c_str(), v_mc, q_mc);
559	  }
560	
561	  // v6 incompatibility surface: the QEMU1 drain's write-mask records which
562	  // config CSRs the program actually wrote; any of them this engine does not
563	  // implement would TRAP on its silicon (the program would never reach the
564	  // ROI), yet the hybrid restore silently skipped it. Warn -- the figure may
565	  // not represent this engine running this program.
566	  {
567	    const std::string w = unsupported_written_warning(
568	        r.phases[0].st, acc->andes_csrs, acc->id);
569	    if (!w.empty() && log_on(kLogWarn)) std::fputs(w.c_str(), stderr);
570	  }
571	
572	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
573	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
574	  // halt pc, and diff the two drains in-process. The oracle plan gets its
575	  // own fresh mmap: reusing the main run's would boot the oracle on the
576	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
577	  // output was already relayed from the main run.
578	  if (cli.verify) {
579	    char pcbuf[32];
580	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
581	                  static_cast<unsigned long long>(r.phases[1].st.pc));
582	    Trigger vtrig;
583	    vtrig.kind = "verify-" + trig.kind;
584	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
585	    vtrig.params["drain_pc"] = pcbuf;
586	
587	    Plan vplan;
588	    vplan.elf = elf_path;
589	    vplan.mem_size = mem;
590	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
591	    // The oracle must model the same hardware as the main run's accurate
592	    // engine ({vlen}/{qemu_cpu}/-readconfig sync) -- without this it ran the
593	    // family-default CPU and false-diffed on vlenb (and, on an H-capable
594	    // engine, on mideleg's read-only-one delegation bits).
595	    vplan.hw_engine_id = acc->id;
596	
597	    log_line(kLogDebug,
598	             "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
599	             "exit, pc=%s)",
600	             pcbuf);
601	    const PlanResult vr = run_plan(vplan, disc.engines);
602	    if (!vr.ok()) {
603	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
604	      if (!vr.repro_dir.empty())
605	        std::fprintf(stderr,
606	                     "[andesim] repro: kept run artifacts at %s "
607	                     "(see manifest.txt)\n",
608	                     vr.repro_dir.c_str());
609	      return 1;
610	    }
611	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
612	    // engine does not implement (it never restored/re-read them; comparing
613	    // would false-diff). Mirrors the resume/drain gating in vsim.
614	    const DiffReport d =
615	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
616	    print_diff_report(d);
617	    if (!d.ok()) {
618	      std::fprintf(stderr,
619	                   "andesim run --verify: vsim drain diverges from the "
620	                   "QEMU oracle\n");
621	      return 1;
622	    }
623	    log_result(kLogInfo, "[verify] PASS: vsim drain matches the QEMU oracle");
624	  }
625	
626	  log_result(kLogDebug, "PASS: --mode hybrid --trigger %s (%s)",
627	             trig.kind.c_str(), elf.stem().string().c_str());
628	  return 0;
629	}
630	
631	}  // namespace
632	
633	int cmd_run(const Cli& cli) {
634	  if (cli.model.empty()) {
635	    std::fprintf(stderr,
636	                 "andesim run: --mode fast|cycle|hybrid is required "
637	                 "(pick the composition; see 'andesim run --help')\n");
638	    return 2;
639	  }
640	  if (!find_model(cli.model)) {
641	    std::fprintf(stderr,
642	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
643	                 cli.model.c_str());
644	    return 2;
645	  }
646	  if (!cli.gdb_port.empty() && !cli.gdb) {
647	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
648	    return 2;
649	  }
650	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
651	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
652	  if (cli.gdb && cli.model == "hybrid") {
653	    std::fprintf(stderr,
654	                 "andesim run: --gdb is not supported with --mode hybrid\n");
655	    return 2;
656	  }
657	  // --print-memmap prints the HYBRID composition's guest memory map (the
658	  // regions both engines support across the handoff); fast/cycle run one
659	  // engine's native map, which andesim does not model.
660	  if (cli.print_memmap && cli.model != "hybrid") {
661	    std::fprintf(stderr,
662	                 "andesim run: --print-memmap requires --mode hybrid (it "
663	                 "prints the hybrid-supported guest memory map)\n");
664	    return 2;
665	  }
666	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
667	  // composition has a second engine to check.
668	  if (cli.verify && cli.model != "hybrid") {
669	    std::fprintf(stderr,
670	                 "andesim run: --verify requires --mode hybrid (the %s "
671	                 "model has nothing to cross-check)\n",
672	                 cli.model.c_str());
673	    return 2;
674	  }
675	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
676	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
677	  // handoff builds itself, so there is no single "the engine" to forward to.
678	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
679	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
680	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
681	    std::fprintf(stderr,
682	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
683	                 "builds both legs' command lines; use --kanata/--objdump for "
684	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
685	    return 2;
686	  }
687	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
688	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
689	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
690	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
691	  // window), so reject instead of measuring something the user did not ask for.
692	  if (!cli.trigger.empty() && cli.model != "hybrid") {
693	    std::fprintf(stderr,
694	                 "andesim run: --trigger applies only to --mode hybrid "
695	                 "(the ROI delimiter); fast/cycle run the whole program\n");
696	    return 2;
697	  }
698	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
699	    std::fprintf(stderr,
700	                 "andesim run: --pc-end applies only to --mode hybrid "
701	                 "--trigger pc\n");
702	    return 2;
703	  }
704	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
705	    std::fprintf(stderr,
706	                 "andesim run: --pc-start applies only to --mode hybrid "
707	                 "--trigger pc\n");
708	    return 2;
709	  }
710	  if (cli.model == "fast") return run_fast(cli);
711	  if (cli.model == "cycle") return run_accurate(cli);
712	  return run_hybrid(cli);  // model validated above; only hybrid remains
713	}
714	
715	}  // namespace andes_sim
