123	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
124	// from deep inside the engine. Both directions. Returns "" when they agree, when
125	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
126	// declares no xlen (cannot judge). Shared by cycle, hybrid, and profile: one
127	// wording.
128	inline std::string elf_engine_arch_error(const std::string& elf,
129	                                         const EngineDescriptor& eng) {
130	  const int ex = elf_xlen(elf);
131	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
132	  char buf[256];
133	  std::snprintf(buf, sizeof(buf),
134	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
135	                "or an rv%d ELF",
136	                ex, eng.id.c_str(), eng.xlen, ex);
